require __DIR__.'/../api/life/store.php';
$checks=0;
function expectGoal(bool $ok,string $message):void{global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}
function freshGoalStore():LifeStore{$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$s=new LifeStore($db);$s->initialize('test-only-long-passphrase');return $s;}
function saveGoal(LifeStore $s,array $args,string $action='goal.save',string $role='owner'):array{$d=$s->read();return $s->mutate($d['version'],$action,$args,$role);}
function lastGoal(LifeStore $s):array{$g=$s->read()['state']['goals'];return end($g);}
function badGoal(LifeStore $s,array $args,int $status=422,string $action='goal.save'):void{$before=$s->read();try{saveGoal($s,$args,$action);}catch(LifeError $e){expectGoal($e->status===$status,'Expected rejection status');expectGoal($s->read()===$before,'Rejected goal write is atomic');return;}throw new RuntimeException('Expected rejected goal write: '.json_encode($args));}
function seedGoals(LifeStore $s,array $goals,array $extra=[]):void{$state=array_merge($s->read()['state'],$extra,['goals'=>$goals]);$s->db->prepare('UPDATE life_board SET state=? WHERE id=?')->execute([json_encode($state,JSON_THROW_ON_ERROR),$s->tenantId]);}
